import socket


def get_tcp_socket(ip_addr):
    proto = socket.getprotobyname("tcp")
    sckt = socket.socket(get_socket_type(ip_addr), socket.SOCK_STREAM, proto)
    sckt.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    return sckt


def get_sctp_socket(ip_addr):
    sctp_proto = socket.getprotobyname("sctp")
    sckt = socket.socket(get_socket_type(ip_addr), socket.SOCK_STREAM, sctp_proto)
    sckt.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    return sckt


def connect(socket, ip, port):
    socket.settimeout(10)
    socket.connect((ip, port))
    socket.settimeout(None)


def send(socket, data):
    data_len = len(data)
    total = 0
    while total < data_len:
        sent = socket.send(data[total:])
        if sent == 0:
            raise Exception(f"Cannot send: Bytes to send={data_len}, bytes sent={total}")
        total += sent


def recv(socket):
    size = 128 * 1024
    data = socket.recv(size)
    if len(data) < size:
        return data

    socket.setblocking(0)
    while True:
        try:
            data_tmp = socket.recv(size)
            data += data_tmp
            if len(data_tmp) < size:
                break
        except socket.error as serr:
            print("Socket error in non-blocking mode:" + str(serr))
            break
    socket.setblocking(1)
    return data


def get_socket_type(ip_addr):
    try:
        if ':' in str(ip_addr):
            return socket.AF_INET6
    except Exception as exc:
        print("Cannot check socket type: {}".format(exc))
    return socket.AF_INET
